import pandas as pd
import numpy as np
import json, sys, os, datetime, base64
from pathlib import Path

sys.stdout.reconfigure(encoding='utf-8')

# ── PLANTILLA HTML (embebida) ─────────────────────────────────────────
TEMPLATE_B64 = """"""

SCRIPT_DIR = Path(os.path.abspath(__file__)).parent

# ── BUSCAR EXCEL ──────────────────────────────────────────────────────
patterns = ['*MEDICION*EMPLEADO*', '*MEDICION*MES*', '*EMPLEADO*MES*',
            '*empleado*mes*', '*medicion*']
excel_files = []
for p in patterns:
    excel_files += list(SCRIPT_DIR.glob(p))
    excel_files += list(SCRIPT_DIR.glob('**/' + p))
excel_files = [f for f in excel_files
               if f.suffix.lower() in ('.xlsx', '.xls')
               and '~$' not in f.name]
excel_files = list({f.resolve(): f for f in excel_files}.values())

if not excel_files:
    print("=" * 50)
    print("ERROR: No se encontro el archivo Excel.")
    print("Coloca el archivo Excel en la misma carpeta:")
    print(f"  {SCRIPT_DIR}")
    print("=" * 50)
    input("Presiona Enter para cerrar...")
    sys.exit(1)

excel_path = max(excel_files, key=lambda f: f.stat().st_mtime)
print(f"Archivo encontrado: {excel_path.name}")

# ── LEER EXCEL ────────────────────────────────────────────────────────
try:
    sheet_names = pd.ExcelFile(excel_path).sheet_names
    sheet = next(
        (s for s in sheet_names
         if 'logistica' in s.lower() or 'transaction' in s.lower()),
        sheet_names[0]
    )
    print(f"Hoja: {sheet}")
    df = pd.read_excel(excel_path, sheet_name=sheet)
    print(f"Filas leidas: {len(df):,}")
except Exception as e:
    print(f"ERROR leyendo Excel: {e}")
    input("Presiona Enter para cerrar...")
    sys.exit(1)

# ── LIMPIAR ───────────────────────────────────────────────────────────
if 'CAJAS RECIBIDAS' in df.columns:
    df = df[df['CAJAS RECIBIDAS'] < 10000].copy()

MONTAC = {
    'WAGNER BAUTISTA RAMIREZ', 'MANUEL  HERNANDEZ CONTANSA',
    'HECTOR PEREZ', 'Josue Hernandez Salazar', 'BRYAN LEE'
}
AUXILIAR = {
    'VERONICA CARRETO', 'Maria Valiente', 'CELESTE ALVAREZ CHUQUIEJ',
    'IRMA CELESTE ORELLANA', 'CARLOS HURTADO MONTENEGRO',
    'CRISTIAN ICAL VAIDEZ', 'David Orlando Najarro'
}

def ph(t):
    try: return int(str(t).split(':')[0])
    except: return -1

def pm(t):
    try:
        p = str(t).split(':')
        return int(p[0]) * 60 + int(p[1])
    except: return -1

df['StartHour'] = df['TrxStartTime'].apply(ph)
df['StartMin']  = df['TrxStartTime'].apply(pm)
df['Month']     = df['TrxDate'].dt.to_period('M').astype(str)
df['Year']      = df['TrxDate'].dt.year.astype(str)
df['DayNum']    = df['TrxDate'].dt.day
df['DayOfWeek'] = df['TrxDate'].dt.dayofweek

# ── AGREGAR ───────────────────────────────────────────────────────────
def build(subset, is_aux):
    result = {}
    inbound = subset[subset['TranType'].isin([151, 547])].copy() if is_aux else subset.copy()
    cajas_col   = 'CAJAS RECIBIDAS' if 'CAJAS RECIBIDAS' in subset.columns else None
    elapsed_col = 'ElapsedTime'      if 'ElapsedTime'      in subset.columns else None

    for user, udf in subset.groupby('UserName'):
        uname = user.replace('MANUEL  ', 'MANUEL ')
        result[uname] = {}
        udf_in = inbound[inbound['UserName'] == user]

        combos = [('_all', udf, udf_in)]
        for y, ydf in udf.groupby('Year'):
            yin = udf_in[udf_in['Year'] == y]
            combos.append(('Y' + str(y), ydf, yin))
            for m, mdf in ydf.groupby('Month'):
                combos.append((str(m), mdf, yin[yin['Month'] == m]))

        for key, pdf, pdf_in in combos:
            by_day_num = {str(int(d)): int(c) for d, c in pdf.groupby('DayNum').size().items()}
            by_hour    = {str(int(h)): int(c) for h, c in pdf.groupby('StartHour').size().items() if h >= 0}

            ds = pdf.groupby('TrxDate')['StartHour'].min()
            avg_s = round(float(ds[ds >= 0].mean()), 2) if (ds >= 0).any() else 0

            df1 = pdf_in.groupby('TrxDate')['StartMin'].min()
            first_min = round(float(df1[df1 >= 0].mean()), 1) if (df1 >= 0).any() else 0

            result[uname][key] = {
                'transactions': int(len(pdf)),
                'cajas':        int(pdf[cajas_col].sum()) if cajas_col else 0,
                'elapsed':      int(pdf[elapsed_col].sum()) if elapsed_col else 0,
                'by_day_num':   by_day_num,
                'by_hour':      by_hour,
                'avg_start':    avg_s,
                'first_min':    first_min,
            }
    return result

print("Procesando Montacarguistas...")
montac_data = build(df[df['UserName'].isin(MONTAC)].copy(), False)
print("Procesando Auxiliares...")
aux_data    = build(df[df['UserName'].isin(AUXILIAR)].copy(), True)

months = sorted(df['Month'].unique().tolist())
years  = sorted(df['Year'].unique().tolist())
RAW    = {'montac': montac_data, 'aux': aux_data, 'months': months, 'years': years}
RAW_JSON = json.dumps(RAW, ensure_ascii=False)

total_trx = (sum(v['_all']['transactions'] for v in montac_data.values()) +
             sum(v['_all']['transactions'] for v in aux_data.values()))
fecha_gen = datetime.datetime.now().strftime('%d/%m/%Y %H:%M')

print(f"Total transacciones: {total_trx:,}")
print(f"Meses: {months[0] if months else '?'} a {months[-1] if months else '?'}")

# ── GENERAR HTML ──────────────────────────────────────────────────────
template = base64.b64decode(TEMPLATE_B64).decode('utf-8')
html_out = template.replace(
    '###RAW_PLACEHOLDER###',
    'const RAW = ' + RAW_JSON + ';'
)

out_path = SCRIPT_DIR / 'dashboard_equipo.html'
with open(out_path, 'w', encoding='utf-8') as f:
    f.write(html_out)

print(f"")
print(f"Dashboard actualizado: {out_path.name}")
print(f"Tamano: {out_path.stat().st_size // 1024} KB")
print(f"Fecha: {fecha_gen}")
print(f"Archivo Excel: {excel_path.name}")
